import XCTest
@testable import Zoop

final class RecoveryReadingTests: XCTestCase {
    func testActualBackendSerializedResponse() throws {
        // Generated by the Rust adapter from 29 synthetic eight-hour nights.
        let url = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "recovery-insights", withExtension: "json"))
        let decoder = JSONDecoder(); decoder.keyDecodingStrategy = .convertFromSnakeCase
        let insights = try decoder.decode(MorningInsights.self, from: Data(contentsOf: url))
        let reading = try XCTUnwrap(insights.recovery)
        XCTAssertEqual(reading.displayedScore, 75)
        XCTAssertEqual(reading.progress, 0.75)
        XCTAssertEqual(reading.baselineCount, 28)
        XCTAssertEqual(reading.recentCount, 7)
        XCTAssertEqual(reading.referenceSeconds, 28_800)
        XCTAssertEqual(reading.band, "high")
        XCTAssertEqual(reading.limiting, ["hrv", "resting_hr"])
        XCTAssertEqual(insights.metrics.count, 3)
    }
    private func decode(state: String = "ready", score: String = "75", band: String = "high", version: Int = 1, method: String = "zoop-recovery-v1") throws -> RecoveryReading {
        let json = """
        {"version":\(version),"method":"\(method)","state":"\(state)","score":\(score),
         "baseline_count":20,"recent_count":7,"reference_seconds":28800,
         "components":{"hrv":75,"resting_hr":82,"last_sleep":100,"recent_sleep":96},
         "limiting":["hrv"],"conflict":false,"band":"\(band)"}
        """
        let decoder = JSONDecoder(); decoder.keyDecodingStrategy = .convertFromSnakeCase
        return try decoder.decode(RecoveryReading.self, from: Data(json.utf8))
    }

    func testUsesServerScoreAndBandWithoutRecalculation() throws {
        let reading = try decode(score: "61", band: "moderate")
        XCTAssertEqual(reading.value, "61")
        XCTAssertEqual(reading.progress, 0.61)
        XCTAssertEqual(reading.status, "Moderate")
        XCTAssertEqual(reading.limitingText, "HRV")
        XCTAssertEqual(reading.components?.restingHr, 82)
    }
    func testWaitingForSyncIsNotActiveCalculation() throws {
        let waiting = try decode(state: "awaiting_sync", score: "null")
        XCTAssertTrue(waiting.isPending)
        XCTAssertTrue(waiting.isWaitingForSync)
        XCTAssertFalse(waiting.isCalculating)
        XCTAssertEqual(waiting.status, "Waiting for sync")
        XCTAssertTrue(try decode(state: "updating").isCalculating)
        XCTAssertFalse(try decode().isWaitingForSync)
    }
    func testZeroAndHundredAreRealScores() throws {
        XCTAssertEqual(try decode(score: "0", band: "low").value, "0")
        XCTAssertEqual(try decode(score: "0").progress, 0)
        XCTAssertEqual(try decode(score: "100").progress, 1)
    }
    func testNonReadyStatesNeverShowStaleScoreOrArc() throws {
        for state in ["learning", "updating", "awaiting_sync", "no_sleep", "insufficient_data", "insufficient_recent_data", "unusual_signals", "ambiguous_history", "future_state"] {
            let reading = try decode(state: state)
            XCTAssertEqual(reading.value, "—", state)
            XCTAssertNil(reading.progress, state)
            XCTAssertNil(reading.limitingText, state)
        }
    }
    func testInvalidOrMissingScoreDoesNotBecomeZero() throws {
        for score in ["null", "-1", "101"] {
            XCTAssertNil(try decode(score: score).displayedScore)
        }
    }
    func testUnknownBandDoesNotInventAssessment() throws {
        XCTAssertNil(try decode(band: "new_band").displayedScore)
        XCTAssertNil(try decode(version: 2).displayedScore)
        XCTAssertNil(try decode(method: "new_method").displayedScore)
    }
    func testOldInsightsResponseRemainsReadable() throws {
        let json = """
        {"version":2,"day":"2026-11-20","timezone":"UTC","state":"ready","metrics":[],"observations":[],"timing":{"count":0}}
        """
        XCTAssertNil(try JSONDecoder().decode(MorningInsights.self, from: Data(json.utf8)).recovery)
    }
}
